export const legendSecondExpansionDrafts = [
  cultural({code:'S147',id:'el-pescallunes-de-torello',title:'El pescallunes de Torelló',grade:'3',level:'middle',universeIds:['llegendes-mon'],voice:'Algenib',music:'L2',batch:'T-A',
    introduction:'Comprensió oral. El pescallunes de Torelló. Una llegenda de la vall del Ges.',
    summary:'Una nit de lluna plena, un home s’atura al costat del riu amb una idea ben singular.',
    context:'Escoltaràs una llegenda ambientada a la vall del Ges. Un home camina prop del poble en una nit clara. Fixa’t en el que veu i en el que intenta fer.',
    editorialFocus:'3r intermèdia: escena contínua, percepció del protagonista i explicació d’un sobrenom. Cinc preguntes duals. Fantasia humorística pròpia del gènere; sense ridiculitzar la gent d’un municipi ni convertir la llegenda en un fet històric.',
    factualSources:[{label:'Diputació de Barcelona, Mapes de Patrimoni Cultural, Esclatats a Sant Vicenç de Torelló, fitxa 08265-65. Documenta la llegenda del reflex de la lluna i el cove com a origen del sobrenom torellonenc.',url:'https://patrimonicultural.diba.cat/element/esclatats-a-sant-vicenc-de-torello'},{label:'Antoni Prat i Puig, Llegendes i tradicions: a Torelló, Pescallunes. Recull local que identifica la versió de Ramon Vinyeta, Llegendes i Tradicions de la Vall del Ges i dels seus contorns (1979). Contrast de la variant, sense reproduir-ne el redactat.',url:'https://www.vallgesbisaura.com/territori/llegendes-i-tradicions/llegendes-i-tradicions-a-torello-pescallunes/'}],
    illustrationBrief:'Vista nocturna d’un camí vora el riu i les cases de Torelló; un home es dirigeix cap a l’aigua. Sense lluna reflectida, cove ni paraules escrites. El relat s’ha d’entendre sense la imatge.',
    transcript:[d('Adaptació catalana pròpia de la llegenda tradicional, no lectura del recull modern. S’ometen noms de molins i l’adjectivació del text consultat. Es recrea el diàleg breu i s’explica què és un cove. Base L2; cap esquitx, rialla o veu extra.'),
      s('nit','Narrador','Diu una llegenda de Torelló que, una nit de lluna plena, un home tornava cap al molí pel camí del riu. L’aigua era quieta i la lluna s’hi reflectia ben rodona. L’home es va aturar. «Mira on ha anat a parar!», va dir, mirant el cercle de llum que tenia als peus.'),
      s('cove','Narrador','Va pensar que, si s’afanyava, podria treure la lluna de l’aigua. Va anar fins al molí i en va tornar amb un cove, un cistell gros de vímet. El portava agafat amb totes dues mans, procurant no entrebancar-se pel camí.'),
      s('intent','Narrador','A la vora del riu va abaixar el cove fins a ficar-lo dins l’aigua. La superfície es va moure i la lluna es va trencar en molts trossets de llum. L’home va esperar. Quan l’aigua es va encalmar, el cercle va tornar a aparèixer, just al mig del cistell.'),
      s('buit','Narrador','«Ara!», va dir. Va estirar el cove enlaire. L’aigua s’escolava entre les tires de vímet i a dins no hi quedava cap lluna. L’home va mirar el riu: la llum tornava a ser allà. Ho va provar una altra vegada, més de pressa, i després una altra, molt a poc a poc.'),
      s('nom','Narrador','Algú que passava pel camí el va veure i li va cridar: «Apa, pescallunes, que al molí t’esperen!» L’home va aixecar els ulls. La lluna continuava penjada al cel. Va agafar el cove buit i va tornar cap al molí. La història va córrer pel poble. Segons la llegenda, d’aquella nit ve el sobrenom de pescallunes que tenen els torellonencs.'),
      d('To de complicitat, sense burla agressiva. No fer de la incomprensió del reflex una explicació científica llarga. Sortida musical comuna després del final.')],
    items:[
      q('lloc','On veu l’home el cercle de llum que vol agafar?','A l’aigua del riu.',['Al sostre del molí.','Al fons del cove buit.','A l’aigua del riu.','Al mig del camí.'],'c','El protagonista veu el reflex de la lluna al riu.',[e('nit','la lluna s’hi reflectia ben rodona')]),
      q('eina','Què va a buscar al molí?','Un cove, un cistell gros de vímet.',['Una canya de pescar.','Un cistell gros de vímet.','Una galleda de metall.','Una xarxa de corda.'],'b','El relat explica la paraula cove abans de fer-la servir a l’acció.',[e('cove','un cove, un cistell gros de vímet')]),
      q('espera','Per què espera després de ficar el cove dins l’aigua?','Perquè la superfície s’encalmi i hi torni a veure el cercle de llum.',['Perquè passi algú que l’ajudi a aixecar-lo.','Perquè el cistell s’ompli de peixos.','Perquè la lluna pugi més amunt del molí.','Perquè l’aigua s’encalmi i torni a veure el cercle.'],'d','El moviment de l’aigua desfigura el reflex; després el cercle reapareix.',[e('intent','La superfície es va moure i la lluna es va trencar en molts trossets de llum'),e('intent','Quan l’aigua es va encalmar, el cercle va tornar a aparèixer')],2),
      q('resultat','Què hi queda al cove quan el treu del riu?','No hi queda cap lluna; l’aigua s’escola entre el vímet.',['Cap lluna; l’aigua passa entre el vímet.','Una lluna petita amagada sota l’aigua.','Els trossets de llum que volia recollir.','Un cercle d’aigua que no pot sortir-ne.'],'a','El cistell no pot retenir el reflex que el protagonista vol pescar.',[e('buit','L’aigua s’escolava entre les tires de vímet i a dins no hi quedava cap lluna')]),
      q('sobrenom','Què explica aquesta llegenda sobre la gent de Torelló?','Per què tenen el sobrenom de pescallunes.',['Per què tots treballaven dins un molí.','Per què el riu havia deixat de portar aigua.','Per què tenen el sobrenom de pescallunes.','Per què es fabriquen coves només de nit.'],'c','El final relaciona el nom amb l’aventura que s’explica al poble.',[e('nom','d’aquella nit ve el sobrenom de pescallunes que tenen els torellonencs')])
    ]}),
  cultural({code:'S148',id:'les-quatre-barres-de-la-llegenda',title:'Les quatre barres de la llegenda',grade:'5',level:'middle',universeIds:['llegendes-mon'],voice:'Erinome',music:'L3',batch:'T-C',
    introduction:'Comprensió oral. Les quatre barres de la llegenda. Una llegenda sobre Guifré el Pelós.',
    summary:'Després d’una batalla, un comte rep una visita. Un escut daurat ocupa un lloc central en la conversa.',
    context:'Algunes llegendes expliquen l’origen d’un símbol conegut. Aquesta tracta de Guifré el Pelós i un escut. Escolta què demana el comte i com la narració relaciona un gest amb aquest símbol.',
    editorialFocus:'5è intermèdia: relat d’origen simbòlic amb una escena principal. Sis preguntes duals sobre motius, seqüència i abast de la narració. S’explicita des de l’inici el caràcter llegendari; no ensenyar l’episodi com a origen històric demostrat de l’heràldica.',
    factualSources:[{label:'Museu d’Història de Catalunya, guia de visita, segona planta: La llegenda de les quatre barres. Contrast del premi al vassall, escut d’or i quatre dits amb sang.',url:'https://www.mhcat.cat/enmhc/visiting_the_museum/plano_libreria/guide_to_visit_the_museum/audio_guide/guia_de_visita_al_museu/segona_planta'},{label:'Museu d’Història de Catalunya, Materials didàctics, Itinerari bàsic, educació secundària: La llegenda de les quatre barres. Distingeix la llegenda de la història de l’escut i identifica Carles el Calb en aquesta variant.',url:'https://drac.cultura.gencat.cat/bitstream/handle/20.500.12368/32971/Materials%20did%C3%A0ctics.%20Itinerari%20b%C3%A0sic%20-%20un%20viatge%20a%20trav%C3%A9s%20de%20la%20hist%C3%B2ria.%20Educaci%C3%B3%20Secund%C3%A0ria%20Obligat%C3%B2ria.pdf?isAllowed=y&sequence=1'},{label:'Ajuntament de Navès, Monument al comte Guifré el Pelós. Testimoni municipal de la variant amb Carles el Calb i l’escut daurat.',url:'https://www.naves.cat/el-municipi/turisme/monument-al-comte-guifre-el-pelos'}],
    illustrationBrief:'Interior d’una tenda medieval amb el comte assegut, sense ferides visibles, i un visitant al costat. Un escut tapat recolzat en una paret. Sense sang, dits marcats ni barres visibles que donin les respostes.',
    transcript:[d('Adaptació pròpia de la variant de Carles el Calb dels materials didàctics del MHC i de Navès. La guia web del museu recull una altra variant, amb Lluís el Pietós. Diàleg i posada en escena recreats. Sense dates, enemics identificats ni mort del comte; no és una reconstrucció històrica. Es descriu sang de manera breu, sense detall gràfic. Base L3 contínua i cap efecte de batalla.'),
      s('relat','Narrador','Una llegenda explica així l’origen de les quatre barres vermelles damunt un fons daurat. El protagonista és el comte Guifré el Pelós. El relat el situa al costat del rei Carles el Calb, després d’una batalla en què els homes del comte han ajudat els del rei.'),
      s('visita','Narrador','Guifré ha quedat ferit i descansa dins d’una tenda. Les armes són a un costat i, recolzat a prop seu, hi ha el seu escut, tot daurat, encara sense cap dibuix. El rei entra a veure’l. Vol donar-li les gràcies per l’ajuda i li pregunta quina recompensa voldria rebre.'),
      s('demanda','Narrador','El comte assenyala l’escut. «M’agradaria tenir un senyal propi», li diu. «Una marca per al meu escut que es pugui reconèixer.» Fins aleshores, aquella superfície daurada no portava cap emblema. El comte voldria que el senyal també el poguessin fer servir els seus descendents.'),
      s('gest','Narrador','El rei s’acosta al comte. Mulla quatre dits en la sang de la seva ferida i els passa sobre l’escut, de dalt a baix. Quan aparta la mà, hi queden quatre ratlles vermelles, l’una al costat de l’altra. El daurat de l’escut es continua veient entre les ratlles.'),
      s('senyal','Narrador','«Aquest serà el teu senyal», diu el rei. Guifré mira la marca que acaba d’aparèixer. L’escut que abans tenia una superfície llisa ara porta els quatre traços. En aquesta versió de la llegenda, el gest del rei és la recompensa que rep el comte pel seu ajut.'),
      s('final','Narrador','La història s’ha anat explicant amb canvis al llarg del temps. Aquesta és la que fa servir els quatre dits per explicar les barres i l’escut d’or per explicar el fons groc. És una narració llegendària sobre un símbol; el seu origen històric s’estudia amb documents i representacions antics. Aquí, el relat acaba amb el comte contemplant el seu escut marcat.'),
      d('To de narració i no de butlletí de la Mar, malgrat el timbre compartit. Mantenir el pas de llegenda a comentari final clar; no afegir fanfares de victòria o èpica bèl·lica.')],
    items:[
      q('visita','Per què el rei visita el comte després de la batalla?','Per agrair-li l’ajuda i oferir-li una recompensa.',['Per demanar-li que torni immediatament a lluitar.','Per agrair-li l’ajuda i oferir-li una recompensa.','Per comprovar si ha perdut el seu escut.','Per encarregar-li que busqui un dibuix antic.'],'b','La visita respon al suport que el comte ha prestat al rei.',[e('visita','Vol donar-li les gràcies per l’ajuda i li pregunta quina recompensa voldria rebre')]),
      q('escut','Com és l’escut abans del gest del rei?','Tot daurat i sense cap dibuix o emblema.',['Daurat amb quatre ratlles negres.','Vermell amb una marca daurada.','Tot daurat i sense cap dibuix.','De fusta amb l’emblema del rei.'],'c','El canvi de l’escut és el centre de la narració.',[e('visita','tot daurat, encara sense cap dibuix')]),
      q('vol','Quina recompensa demana el comte?','Un senyal propi per a l’escut, que també puguin fer servir els descendents.',['Un escut nou fet amb un altre metall.','Unes armes que només pugui fer servir el rei.','Un dibuix que es pugui esborrar després de la batalla.','Un emblema propi que també puguin usar els descendents.'],'d','La petició té a veure amb una marca recognoscible i continuada.',[e('demanda','Una marca per al meu escut que es pugui reconèixer'),e('demanda','també el poguessin fer servir els seus descendents')],2),
      q('ratlles','Com apareixen les quatre ratlles vermelles segons la llegenda?','El rei passa sobre l’escut quatre dits mullats en la sang de la ferida.',['El rei hi passa quatre dits mullats en sang.','El comte hi dibuixa quatre línies amb la seva espasa.','Un pintor hi copia les marques d’un escut antic.','El rei hi enganxa quatre cintes que duia a la tenda.'],'a','Els quatre dits deixen els quatre traços damunt el fons daurat.',[e('gest','Mulla quatre dits en la sang de la seva ferida i els passa sobre l’escut')]),
      q('fons','Amb què relaciona el relat el fons groc del símbol?','Amb el color daurat que ja tenia l’escut.',['Amb la llum que entra a la tenda del rei.','Amb les armes que hi ha al costat del comte.','Amb el color daurat que ja tenia l’escut.','Amb una capa de pintura afegida després de les ratlles.'],'c','L’escut ja és daurat abans de rebre les marques.',[e('final','l’escut d’or per explicar el fons groc')]),
      q('abast','Com presenta l’àudio aquest origen de les barres?','Com una llegenda sobre el símbol, diferenciada de l’estudi del seu origen històric.',['Com un document escrit pels participants en la batalla.','Com una llegenda diferenciada de l’estudi històric.','Com una explicació del procés actual de pintar escuts.','Com una notícia sobre una troballa feta dins una tenda.'],'b','El relat es presenta com a llegenda i el tancament situa com es pot estudiar la història del símbol.',[e('relat','Una llegenda explica així l’origen'),e('final','el seu origen històric s’estudia amb documents i representacions antics')],2)
    ]}),
  cultural({code:'S149',id:'guillem-tell-i-la-poma',title:'Guillem Tell i la poma',grade:'5',level:'middle',universeIds:['llegendes-mon'],voice:'Puck',music:'L1',batch:'T-B',
    introduction:'Comprensió oral. Guillem Tell i la poma. Un episodi d’una llegenda de Suïssa.',
    summary:'Guillem Tell travessa una plaça amb el seu fill. Una ordre del governador els posa en una situació perillosa.',
    context:'Escoltaràs un episodi de la llegenda suïssa de Guillem Tell. Hi apareixen una imposició del governador, una prova arriscada i un viatge. La història es presenta com a llegenda, no com una crònica comprovada.',
    editorialFocus:'5è intermèdia: cadena causal amb tres espais i canvi de les condicions d’un presoner. Sis preguntes duals. Amistat familiar, coerció i amenaça breu sense detall gràfic; no presentar la prova com un joc imitable.',
    factualSources:[{label:'Presence Switzerland, Departament Federal d’Afers Exteriors de Suïssa, William Tell, a symbol of Switzerland known throughout the world. Contrast de barret, poma, segona sageta, detenció i fugida de la barca.',url:'https://www.aboutswitzerland.eda.admin.ch/en/william-tell-a-symbol-of-switzerland-known-throughout-the-world'},{label:'Museu Nacional Suís, The Swiss foundation legend. Reprodueix i contextualitza la crònica de Petermann Etterlin (1507) i l’escena de les dues sagetes.',url:'https://blog.nationalmuseum.ch/en/2017/08/the-swiss-foundation-legend/'}],
    illustrationBrief:'Plaça antiga suïssa amb un pare i un fill que arriben a peu; muntanyes al fons. Sense poma sobre el cap, armes apuntant, barca o barret a la vista. Cap escena de perill gràfic.',
    transcript:[d('Adaptació pròpia d’un episodi de la llegenda, fins a la fugida de la barca. S’omet la venjança mortal posterior i el context polític detallat. No s’atribueix historicitat demostrada a Tell. La referència a la segona sageta es manté perquè motiva la detenció. L1 molt baixa; cap tret, crit, tempesta forta o so que tapi la parla.'),
      s('placa','Narrador','La llegenda de Guillem Tell se situa en una vall de Suïssa. El governador havia fet posar el seu barret al capdamunt d’un pal, al mig de la plaça. Havia ordenat que tothom el saludés inclinant el cap, com si ell mateix fos allà. Un dia, Tell va passar per la plaça amb el seu fill i va continuar caminant sense saludar el barret.'),
      s('prova','Narrador','Els soldats el van aturar. El governador sabia que Tell era molt bon tirador amb la ballesta, una arma que llança sagetes. Li va imposar una prova terrible: havia de tocar una poma col·locada damunt del cap del seu fill. Si ho aconseguia, li perdonaria haver desobeït l’ordre.'),
      s('poma','Narrador','Tell va preparar dues sagetes. En va guardar una sota la roba i va posar l’altra a la ballesta. El nen es va quedar al lloc indicat, amb la poma al cap. Tell va apuntar i va disparar. La sageta va tocar la poma i el fill va quedar il·lès.'),
      s('segona','Narrador','Però el governador havia vist la segona sageta. «Per què la volies?», li va preguntar. Tell va acabar confessant que l’hauria fet servir contra ell si hagués ferit el seu fill. El governador, furiós, el va fer empresonar. La prova estava superada, però ara l’acusava per aquella amenaça.'),
      s('barca','Narrador','Els soldats van pujar Tell a una barca per portar-lo fins al castell. A mig llac es va aixecar una tempesta. El vent empenyia l’embarcació i els guàrdies tenien por d’enfonsar-se. Tell també era un bon barquer. Li van treure les lligadures perquè els ajudés a conduir la barca fins a la riba.'),
      s('fugida','Narrador','Quan van ser prou a prop de terra, Tell va aprofitar la confusió i va saltar fora de l’embarcació. Va fugir dels guàrdies i es va allunyar del llac. Aquest episodi de la llegenda acaba amb Tell lliure, després que la tempesta hagi fet canviar el seu paper: de presoner lligat a l’home que havia de conduir la barca.'),
      d('Una sola veu; contrastar l’autoritat del governador i la tensió de Tell amb intenció, no amb imitacions de timbres. No afegir la continuació violenta o una moral sobre l’obediència.')],
    items:[
      q('ordre','Quina ordre incompleix Tell a la plaça?','La d’inclinar el cap per saludar el barret del governador.',['La de deixar la ballesta fora del poble.','La de tornar al castell abans que es faci fosc.','La d’inclinar el cap davant del barret.','La de travessar la plaça sense companyia.'],'c','El barret representa la presència i l’autoritat del governador.',[e('placa','que tothom el saludés inclinant el cap'),e('placa','sense saludar el barret')]),
      q('condicio','Què ha de fer per superar la prova imposada?','Tocar amb una sageta una poma damunt del cap del seu fill, sense ferir-lo.',['Tocar la poma que té el fill al cap sense ferir-lo.','Fer caure el barret del pal amb dues sagetes.','Arribar al castell amb la poma abans de la tempesta.','Tocar dues pomes que els soldats han penjat al pal.'],'a','La prova posa el fill en perill i Tell l’encerta.',[e('prova','tocar una poma col·locada damunt del cap del seu fill'),e('poma','el fill va quedar il·lès')],2),
      q('reserva','Què explica Tell sobre la sageta que havia guardat?','Que l’hauria feta servir contra el governador si hagués ferit el fill.',['Que era un regal per al seu fill després de la prova.','Que l’hauria dirigida contra el governador si feria el fill.','Que la necessitava per conduir la barca durant el viatge.','Que l’havia trobada al terra quan passava per la plaça.'],'b','L’explicació de la reserva provoca la reacció del governador.',[e('segona','l’hauria fet servir contra ell si hagués ferit el seu fill')]),
      q('detencio','Per què el governador el fa empresonar després d’haver encertat la poma?','Per l’amenaça que revela en explicar l’ús de la segona sageta.',['Perquè la primera sageta no havia tocat la poma.','Perquè s’ha negat a conduir la barca fins al castell.','Perquè el fill ha amagat el barret del governador.','Per l’amenaça relacionada amb la segona sageta.'],'d','La detenció respon a l’amenaça confessada, no a haver fallat la prova.',[e('segona','ara l’acusava per aquella amenaça')],2),
      q('lligadures','Per què els guàrdies li treuen les lligadures a la barca?','Perquè, com a bon barquer, els ajudi a arribar a la riba durant la tempesta.',['Perquè saben que pot conduir la barca fins a la riba.','Perquè el governador ha ordenat deixar-lo lliure al llac.','Perquè ha promès que els regalarà la seva ballesta.','Perquè necessiten que recuperi una sageta de l’aigua.'],'a','La tempesta fa que necessitin la seva habilitat com a barquer.',[e('barca','Tell també era un bon barquer'),e('barca','Li van treure les lligadures perquè els ajudés a conduir la barca fins a la riba')],2),
      q('fugida','Quina situació aprofita Tell per fugir?','Que s’han acostat a terra i els guàrdies estan confosos.',['Que els guàrdies es queden adormits al castell.','Que el seu fill torna amb una segona barca.','Que és prop de terra i hi ha confusió a la barca.','Que la tempesta fa desaparèixer tota la riba.'],'c','La proximitat de terra permet saltar fora de l’embarcació.',[e('fugida','Quan van ser prou a prop de terra, Tell va aprofitar la confusió i va saltar fora de l’embarcació')])
    ]}),
  cultural({code:'S150',id:'el-gegant-i-lagullola',title:'El gegant i l’Agullola',grade:'4',level:'easy',universeIds:['llegendes-mon'],voice:'Algenib',music:'L2',batch:'T-A',
    introduction:'Comprensió oral. El gegant i l’Agullola. Una llegenda de Rupit.',
    summary:'Un gegant molt estimat ha de marxar de les muntanyes on viu. Abans de fer-ho, vol deixar-hi un record.',
    context:'Les llegendes sovint relacionen la forma d’una muntanya amb un personatge fantàstic. Aquesta passa a la zona de Rupit. Escolta què hi fa un gegant abans de marxar.',
    editorialFocus:'4t accessible: variant amable documentada d’una llegenda de formació del paisatge. Cinc preguntes duals amb una acció central i causa pròxima. Els diàlegs de comiat són recreació declarada; el gegant bo no es barreja amb la variant del dimoni i sant Miquel.',
    factualSources:[{label:'Diputació de Barcelona, Mapes de Patrimoni Cultural, El gegant de l’Agullola, fitxa 08901-190, apartat Observacions. Documenta explícitament la variant del gegant bo i estimat que deixa un record amb un cop de destral. Registre de dades obertes.',url:'https://do.diba.cat/data/ds/patrimoni_cultural/graella?municipis=08901&sort_field=coordenades&sort_ord=asc'}],
    illustrationBrief:'Muntanyes de Rupit amb un gegant al costat d’un camí i el poble a la llunyania. No mostrar habitants ni salutacions, destral, roca separada, cop o forma final de l’Agullola. L’expressió no anticipa la seva relació amb la gent.',
    transcript:[d('Adaptació catalana pròpia de la variant del gegant bo, documentada a les observacions de la fitxa DIBA 08901-190. El comiat, les veus del poble i la caminada són recreacions per donar continuïtat al nucli tradicional: gegant estimat, record, cop de destral i Agullola. No importar la lluita ni la identitat diabòlica d’una altra variant. L2 molt atenuada; cap cop sonor sobtat.'),
      s('gegant','Narrador','A prop de Rupit s’alça una roca alta i estreta, separada del cingle que té al costat. En diuen l’Agullola. Una llegenda explica que aquella roca va quedar així pel comiat d’un gegant. En la versió que escoltarem, el gegant era bo i la gent de la contrada l’estimava.'),
      s('vida','Narrador','Quan el veien passar pels camins, aixecaven el braç per saludar-lo. Ell havia de mirar bé on posava els peus: un sol pas seu era molt més llarg que el camí que podia fer una persona d’una gambada. Quan s’asseia a descansar, des del poble encara se li veien les espatlles per damunt dels arbres.'),
      s('marxar','Narrador','Un dia va arribar l’hora de marxar cap a unes altres muntanyes. La gent es va reunir per acomiadar-lo. «Ens vindràs a veure?», li van preguntar. El gegant va mirar els camins i les cases. «M’agradaria deixar-vos un record», va respondre. Va estar una estona observant la paret de roca que s’aixecava més enllà del poble.'),
      s('destral','Narrador','Després va caminar fins al cingle de Sant Joan de Fàbregues. Va agafar la seva destral i va donar un cop a la roca. El tall va separar un tros alt i estret de la resta del cingle. Entre aquella agulla de pedra i la paret de la muntanya hi va quedar un espai buit.'),
      s('record','Narrador','El gegant va guardar la destral i es va girar per dir adeu. La gent el va veure allunyar-se fins que va desaparèixer darrere les muntanyes. La roca es va quedar al mateix lloc. Segons aquesta llegenda, és el record que el gegant va deixar abans de marxar, l’Agullola que encara es veu a prop de Rupit.'),
      d('Veu càlida i de comiat, sense atribuir al gegant oficis o obres que la font no documenta. La música situa el relat; la separació de la roca només s’explica amb paraules. Fosa final curta.')],
    items:[
      q('forma','Com és la roca que anomenen l’Agullola?','Alta i estreta, separada del cingle del costat.',['Baixa i rodona, amagada sota un riu.','Alta i estreta, separada del cingle.','Plana i ampla, damunt de les cases.','Petita i llisa, al mig d’una plaça.'],'b','La forma es presenta abans d’explicar-ne l’origen llegendari.',[e('gegant','una roca alta i estreta, separada del cingle')]),
      q('relacio','Com tracta la gent el gegant en aquesta versió?','L’estima i el saluda quan el veu passar.',['S’amaga sempre que el veu arribar.','El persegueix perquè ha trencat les cases.','L’estima i el saluda quan passa.','Li demana que no torni mai al poble.'],'c','El relat selecciona expressament la variant del gegant estimat.',[e('gegant','la gent de la contrada l’estimava'),e('vida','aixecaven el braç per saludar-lo')]),
      q('motiu','Per què vol fer alguna cosa abans de marxar?','Per deixar un record a la gent de la contrada.',['Per amagar-se darrere d’una paret més alta.','Per preparar un camí perquè el segueixin.','Per aconseguir que li regalin una destral.','Per deixar un record a la gent del lloc.'],'d','El comiat motiva l’acció del gegant.',[e('marxar','M’agradaria deixar-vos un record')]),
      q('accio','Què fa a la paret de roca?','Hi dona un cop de destral que en separa un tros alt i estret.',['Hi dona un cop de destral i en separa un tros.','Hi apila pedres petites fins a formar una agulla.','Hi obre un forat per construir la seva casa.','Hi dibuixa el camí cap a les altres muntanyes.'],'a','El tall de la destral explica la separació de la roca.',[e('destral','El tall va separar un tros alt i estret de la resta del cingle')]),
      q('lloc','Què queda al lloc quan el gegant ja ha marxat?','L’Agullola, que la llegenda presenta com el seu record.',['La destral que ha regalat als habitants.','Una casa nova amagada entre els arbres.','L’Agullola, com a record del seu comiat.','Un pont per anar a les altres muntanyes.'],'c','El gegant s’enduu la destral i la roca es queda.',[e('record','El gegant va guardar la destral'),e('record','La roca es va quedar al mateix lloc')])
    ]}),
];
